export function pageInfo(total, size, page) {
  const pages = Math.floor(total / size);
  const offset = (page - 1) * size;
  const hasNext = page <= pages;
  return { pages, offset, hasNext };
}

import { pageInfo } from './paginate.mjs';
import assert from 'node:assert';
const cases = [
  { total: 0, size: 10, page: 1, pages: 0, offset: 0, hasNext: false },
  { total: 25, size: 10, page: 1, pages: 3, offset: 0, hasNext: true },
  { total: 25, size: 10, page: 3, pages: 3, offset: 20, hasNext: false },
  { total: 20, size: 10, page: 2, pages: 2, offset: 10, hasNext: false },
  { total: 20, size: 10, page: 3, pages: 2, offset: 10, hasNext: false },
  { total: 5, size: 10, page: 1, pages: 1, offset: 0, hasNext: false },
];
for (const c of cases) {
  const r = pageInfo(c.total, c.size, c.page);
  assert.deepStrictEqual(r, { pages: c.pages, offset: c.offset, hasNext: c.hasNext }, `total=${c.total} size=${c.size} page=${c.page} → ${JSON.stringify(r)}`);
}
console.log('ALL TESTS PASSED');
